Translate("frFR", "duskwood", {
	title = "Bois de la Pénombre",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bois de la Pénombre est une forêt de nuit sans fin au sud du {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Ses vieux arbres se referment au-dessus des têtes, si bien qu'aucun vrai jour n'atteint jamais le sol. Les morts arpentent ses cimetières, des hommes-loups rôdent dans ses bosquets et des araignées nichent le long de ses rivières. À l'est se dresse la ville de {link:darkshire}Darkshire{/link}, où les derniers habitants qui n'ont pas fui gardent leurs torches allumées et leurs portes barrées.]=],
		},
		{
			title = "Origines",
			text = [=[La forêt n'a pas toujours été ainsi. Ceux qui l'ont connue avant les guerres se souviennent de bois verdoyants, de fermes prospères et d'un village qui a pris depuis le nom de {link:darkshire}Darkshire{/link}. Pendant la {link:first-war}Première Guerre{/link}, la {link:horde}Horde{/link} brûla ces bois comme elle brûla {link:elwynn-forest}Elwynn{/link}. Les fermes furent ensuite relevées. Puis, dans les années où les hommes du royaume partirent vers le nord pour la {link:third-war}Troisième Guerre{/link}, vint quelque chose de plus immonde. Une magie que nul à Darkshire ne sait nommer s'infiltra dans la terre. Les feuilles s'assombrirent, les tombes s'ouvrirent, et depuis, la forêt vit dans la pénombre.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Le Bois de la Pénombre est seul. Quand les ténèbres vinrent, {link:stormwind-city}Stormwind{/link} rappela ses gardes et ne les renvoya jamais. La ville leva sa propre milice, le {link:the-night-watch}Guet de nuit{/link}, sous les ordres du commandant {link:commander-althea-ebonlocke}Althea Ebonlocke{/link}, et depuis il tient le cœur de la forêt avec trop peu d'épées. Le Guet n'est pas le seul souci pour la paix de {link:darkshire}Darkshire{/link}. Les seigneurs de Stormwind cassent les sentences de son conseil, et l'un de ses conseillers parle ouvertement de rompre avec la couronne. Au-delà des murs, les {link:nightbane-worgen}worgens Nightbane{/link} ont pris le sud, les morts tiennent {link:raven-hill}Colline-aux-Corbeaux{/link}, des ogres tiennent les tertres du sud, et la {link:defias-brotherhood}Confrérie défias{/link} se sert des fermes de l'ouest comme d'une route pour ses complots. Des {link:dark-riders}cavaliers noirs{/link} sortent du {link:deadwind-pass}Défilé de Deuillevent{/link} à l'est, et nul ne sait ce qu'ils veulent.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les gens de {link:darkshire}Darkshire{/link}.{/b} Des marchands, des forgerons, une voyante, un historien et un conseil qui se réunit encore à l'hôtel de ville. La plupart ont perdu quelqu'un dans la forêt.
• {b}{link:the-night-watch}Le Guet de nuit{/link}.{/b} Des Veilleurs gardent les portes de la ville, la place et une poignée de postes isolés sur les routes.
• {b}La famille {link:carevin-family}Carevin{/link}.{/b} Une maison de chasseurs qui mènent leur propre guerre contre les démons et les morts-vivants.
• {b}Les morts.{/b} Squelettes, goules et esprits sans repos remplissent le {link:raven-hill-cemetery}Cimetière de Colline-aux-Corbeaux{/link} et les {link:tranquil-gardens-cemetery}Jardins paisibles{/link}.
• {b}Les {link:nightbane-worgen}Nightbane{/link}.{/b} Des worgens apparus comme sortis de nulle part, qui tiennent désormais le sud de la forêt.
• {b}Les ogres.{/b} Le clan Splinter Fist occupe le {link:vul-gol-ogre-mound}Tertre des ogres Vul'Gol{/link}.
• {b}Les Réprouvés.{/b} Une petite expédition des {link:forsaken}Réprouvés{/link} se cache au {link:beggar-s-haunt}Repaire des mendiants{/link}, à l'extrême est.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La vieille forêt.{/b} Avant les guerres, la forêt était verte, et ses fermes et ses villages prospéraient.
• {b}La {link:first-war}Première Guerre{/link}.{/b} La {link:horde}Horde{/link} brûla les bois sur sa route vers {link:stormwind-city}Stormwind{/link}.
• {b}L'Assombrissement.{/b} Pendant les années de la {link:third-war}Troisième Guerre{/link}, une magie immonde s'empara de la forêt. {link:raven-hill}Colline-aux-Corbeaux{/link} tomba, et ses habitants avec elle. Stormwind retira ses gardes, et {link:darkshire}Darkshire{/link} leva le {link:the-night-watch}Guet de nuit{/link} à leur place.
• {b}Le temps présent.{/b} Darkshire tient, mais à peine, et ses habitants commencent à se demander si le royaume les compte encore parmi les siens.]=],
		},
		{
			title = "Légendes du bois",
			text = [=[• Les enfants de {link:darkshire}Darkshire{/link} grandissent avec l'histoire d'un bon alchimiste appelé l'{link:abercrombie}Embaumeur{/link}, que le chagrin rendit fou après la mort de sa femme.
• En ville, le nom de {link:stalvan-mistmantle}Stalvan Mistmantle{/link} ne se prononce qu'à voix basse.
• Ceux qui s'égarent dans les bois obscurs racontent parfois qu'une ombre les a ramenés jusqu'à la route.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne dit ce qui assombrit d'abord le Bois de la Pénombre, ni en quelle année cela arriva.]=],
		},
	},
})

Translate("frFR", "darkshire", {
	title = "Darkshire",
	sections = {
		{
			title = "Résumé",
			text = [=[Darkshire est la dernière vraie ville du {link:duskwood}Bois de la Pénombre{/link}, un nœud de maisons de bois autour d'une place, à l'est de la forêt. {link:the-night-watch}Le Guet de nuit{/link} garde ses portes. Le bourgmestre, {link:lord-ello-ebonlocke}Lord Ello Ebonlocke{/link}, tient sa cour à l'hôtel de ville avec son conseil et son greffier. Les voyageurs boivent à la Scarlet Raven Tavern, où le cuisinier sert des gâteaux d'origine douteuse. Une voyante lit les cartes dans une maison de la place, et un historien tient une bibliothèque qui s'amincit chaque année. Ici, les gens laissent leurs lampes brûler toute la nuit.]=],
		},
	},
})

Translate("frFR", "raven-hill", {
	title = "Colline-aux-Corbeaux",
	sections = {
		{
			title = "Résumé",
			text = [=[Colline-aux-Corbeaux fut jadis un fier village à l'ouest du {link:duskwood}Bois de la Pénombre{/link}. C'est aujourd'hui un village fantôme. Ses maisons sont vides, et ses habitants reposent dans le grand cimetière au nord. Peu d'écrits sur le village ont survécu à sa chute, et même l'historien de {link:darkshire}Darkshire{/link} n'en sait pas grand-chose. Depuis peu, les gens de la ville entendent parler d'ombres qui bougent entre les maisons et d'une lumière à une fenêtre. Cette hantise n'était qu'un homme effrayé qui se cachait. Les fantômes de la {link:the-valor-family}famille Valor{/link}, qui défendait jadis le village, sont une autre affaire.]=],
		},
	},
})

Translate("frFR", "raven-hill-cemetery", {
	title = "Cimetière de Colline-aux-Corbeaux",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cimetière de Colline-aux-Corbeaux s'étend sur le nord-ouest du {link:duskwood}Bois de la Pénombre{/link}, si vaste qu'il domine désormais les terres alentour. Les squelettes de ses morts marchent en rangs entre les pierres, et des goules infestent ses mausolées. {link:the-night-watch}Le Guet de nuit{/link} y a envoyé des volontaires encore et encore, et les morts reviennent toujours. C'est ici que le chevalier {link:mor-ladim}Morgan Ladimore{/link} trouva les tombes de sa famille, et ici que sa propre tombe fut plus tard retrouvée vide. Dans une cabane à sa lisière nord vit un vieil ermite. Près de sa porte se trouve la tombe d'une femme nommée {link:eliza}Eliza{/link}.]=],
		},
	},
})

Translate("frFR", "forlorn-rowe", {
	title = "La masure lugubre",
	sections = {
		{
			title = "Résumé",
			text = [=[La masure lugubre est une maison sur une colline qui domine le {link:raven-hill-cemetery}Cimetière de Colline-aux-Corbeaux{/link}. C'est l'antre du nécromancien {link:morbent-fel}Morbent Fel{/link}, et c'est ici que les {link:dark-riders}cavaliers noirs{/link} du {link:deadwind-pass}Défilé de Deuillevent{/link} viennent lui parler. Les squelettes qui gardent la colline sont ses serviteurs. Un temps, il acheta des corps au pilleur de tombes {link:dextren-ward}Dextren Ward{/link}, jusqu'à ce que Ward soit pris et envoyé à la {link:the-stockade}Prison de Stormwind{/link}. {link:sven-yorgen}Sven Yorgen{/link} surveille cette maison depuis son camp à l'ouest, et il attend le jour où elle se taira.]=],
		},
	},
})

Translate("frFR", "manor-mistmantle", {
	title = "Manoir Mistmantle",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Manoir Mistmantle se dresse à peu de distance au nord de {link:darkshire}Darkshire{/link}, maison solitaire sous les arbres noirs. Son maître est {link:stalvan-mistmantle}Stalvan Mistmantle{/link}, un homme qui fut précepteur d'enfants et dont le nom est désormais synonyme de meurtre. Il venait de la {link:silverpine-forest}Forêt des Pins argentés{/link}, loin au nord, et signait jadis ses lettres du nom de sa terre natale. {link:the-night-watch}Le Guet de nuit{/link} le soupçonna longtemps d'anciens meurtres, mais ne put rien prouver. Les gens de la ville évitent la maison, et ceux qui passent devant la nuit ne s'y attardent pas.]=],
		},
	},
})

Translate("frFR", "roland-s-doom", {
	title = "Destin de Roland",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Destin de Roland est une mine au sud du {link:duskwood}Bois de la Pénombre{/link}. On y travaillait déjà durement, mais sans danger mortel, jusqu'au jour où un mineur tira d'un tas de gravats le manche d'une étrange faux. Cette nuit-là, les worgens sortirent de la roche même. La moitié des mineurs moururent dans les premiers instants. Les {link:nightbane-worgen}Nightbane{/link} tiennent toujours la mine, et l'on voit leurs feux de loin. C'est ici que l'on trouva les premiers worgens du Bois de la Pénombre, et ici que s'achève la piste de la {red:scythe-of-elune}Faux d'Elune{/red}.]=],
		},
	},
})

Translate("frFR", "addle-s-stead", {
	title = "Ferme des Addle",
	sections = {
		{
			title = "Résumé",
			text = [=[La Ferme des Addle est une ferme abandonnée au sud-ouest du {link:duskwood}Bois de la Pénombre{/link}, au sud de la route qui vient de la {link:westfall}Marche de l'Ouest{/link}. Ses fermiers sont partis. La {link:defias-brotherhood}Confrérie défias{/link} en a fait un lieu de rendez-vous, et ses lames de la nuit et ses enchanteurs montent la garde parmi les champs en ruine. Il y a quelque temps, le {link:the-night-watch}Guet de nuit{/link} y vit un rassemblement d'agents défias, assez important pour laisser croire que quelque chose de grande valeur y était passé. On dit que le fantôme d'une garde de {link:raven-hill}Colline-aux-Corbeaux{/link} arpente encore ses champs.]=],
		},
	},
})

Translate("frFR", "the-rotting-orchard", {
	title = "Le verger pourrissant",
	sections = {
		{
			title = "Résumé",
			text = [=[Le verger pourrissant s'étend au sud-ouest de {link:darkshire}Darkshire{/link}. Ses arbres se dressent toujours en rangées, mais leurs fruits sont tombés depuis longtemps et ont pourri. Les {link:nightbane-worgen}worgens Nightbane{/link} l'ont envahi. Leurs tisseurs d'ombre et leurs coureurs noirs chassent entre les troncs, et c'est ici que les chasseurs de {link:carevin-family}la famille Carevin{/link} envoient ceux qui veulent les rejoindre. Leur chasseur {link:calor}Calor{/link} a appris que les coureurs noirs forment le gros des Nightbane, et que pour chacun qui tombe, un autre prend bientôt sa place.]=],
		},
	},
})

Translate("frFR", "the-yorgen-farmstead", {
	title = "La ferme des Yorgen",
	aliases = { "Ferme des Yorgen", "Ferme de Sven" },
	sections = {
		{
			title = "Résumé",
			text = [=[La ferme des Yorgen se trouve au sud du {link:duskwood}Bois de la Pénombre{/link}. C'était le foyer de {link:sven-yorgen}Sven Yorgen{/link} et de sa famille, jusqu'à ce que les {link:dark-riders}cavaliers noirs{/link} du {link:deadwind-pass}Défilé de Deuillevent{/link} viennent en l'absence de Sven et massacrent tous ceux qui s'y trouvaient. À son retour, Sven vit une silhouette obscure enterrer quelque chose derrière une vieille souche près de la grange. Ce trou contenait un journal. Il parlait d'un mineur qui avait fui le {link:roland-s-doom}Destin de Roland{/link} et s'était caché dans la grange des Yorgen, et qui avait vu mourir la famille.]=],
		},
	},
})

Translate("frFR", "vul-gol-ogre-mound", {
	title = "Tertre des ogres Vul'Gol",
	aliases = { "Vul'Gol" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Tertre des ogres Vul'Gol est un dédale de grottes au sud du {link:duskwood}Bois de la Pénombre{/link}, tenu par les {link:ogres}ogres{/link} du clan Splinter Fist. Leurs guerriers, leurs tisseurs de feu et leurs contremaîtres pillent les routes et emportent ce qu'ils y trouvent, jusqu'à la caisse d'herbes et d'outils d'un vieil ermite. L'ogre Zzarc'Vul demeure dans le tertre. Il porte un grand monocle qu'un érudit de {link:darkshire}Darkshire{/link} convoite pour ses propres desseins. On pense que le fantôme d'un Veilleur de l'ancienne {link:raven-hill}Colline-aux-Corbeaux{/link} arpente les routes près du tertre, toujours en guerre contre les ogres.]=],
		},
	},
})

Translate("frFR", "brightwood-grove", {
	title = "Bosquet de Clairbois",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bosquet de Clairbois est une étendue de bois du {link:duskwood}Bois de la Pénombre{/link}. La clarté qui lui donna son nom a disparu. Les {link:nightbane-worgen}worgens Nightbane{/link} y chassent, leurs tisseurs d'ombre se déplaçant en meutes entre les arbres, et les chasseurs de {link:darkshire}Darkshire{/link} prononcent le nom du bosquet avec un rire amer. Comme le verger pourrissant, c'est un terrain d'épreuve de {link:carevin-family}la famille Carevin{/link}. Ceux qui veulent se joindre à la guerre des Carevin doivent d'abord revenir vivants de ses ombres.]=],
		},
	},
})

Translate("frFR", "twilight-grove", {
	title = "Bosquet du crépuscule",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bosquet du crépuscule se trouve au cœur du {link:duskwood}Bois de la Pénombre{/link}, au nord de la route qui traverse la forêt. Un grand arbre s'y élève. C'est l'un des rares lieux des {link:eastern-kingdoms}Royaumes de l'est{/link} où le monde éveillé touche le {link:emerald-dream}Rêve d'émeraude{/link}, le royaume que gardent les dragons verts. De telles portes sont rares dans le monde, et les autres se trouvent loin, dans les {link:the-hinterlands}Hinterlands{/link} et en {link:kalimdor}Kalimdor{/link}. Aucun des gens de {link:darkshire}Darkshire{/link} ne parle du bosquet, et nul ne prétend savoir pourquoi un tel lieu se trouve dans une forêt des morts.]=],
		},
	},
})

Translate("frFR", "tranquil-gardens-cemetery", {
	title = "Cimetière des jardins paisibles",
	aliases = { "Jardins paisibles" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cimetière des jardins paisibles s'étend au sud de {link:darkshire}Darkshire{/link}, dans le sud-est du {link:duskwood}Bois de la Pénombre{/link}. Son nom est aujourd'hui une plaisanterie cruelle. Des guerriers et des mages squelettes marchent parmi ses tombes, et une goule démente erre dans ses allées avec un miroir volé. C'est le plus proche de la ville parmi les cimetières de la forêt. Ses squelettes portent dans leur crâne des fleurs de pourriture, que le tavernier de Darkshire distille en une liqueur assez forte pour réveiller les morts. Quand les morts s'y relèvent, le {link:the-night-watch}Guet de nuit{/link} est le premier à l'apprendre.]=],
		},
	},
})

Translate("frFR", "the-hushed-bank", {
	title = "La Rive silencieuse",
	sections = {
		{
			title = "Résumé",
			text = [=[La Rive silencieuse longe la rivière, à l'extrême bord ouest du {link:duskwood}Bois de la Pénombre{/link}. C'est ici que {link:sven-yorgen}Sven Yorgen{/link} tient son camp avec son compagnon Lars et quelques fidèles. Ils sont si peu nombreux qu'aucun ne peut partir chercher des vivres, aussi {link:carevin-family}la famille Carevin{/link} de {link:darkshire}Darkshire{/link} leur envoie ce qu'elle peut. Ils vivent de leur chasse, et des loups redoutables affamés descendent des bois pour leur disputer chaque morceau de viande. De cette rive solitaire, Sven surveille l'est, où le nécromancien {link:morbent-fel}Morbent Fel{/link} attend sur sa colline.]=],
		},
	},
})

Translate("frFR", "the-darkened-bank", {
	title = "La Rive sombre",
	sections = {
		{
			title = "Résumé",
			text = [=[La Rive sombre est la longue lisière nord du {link:duskwood}Bois de la Pénombre{/link}, où la rivière coule entre la forêt et les contreforts d'{link:elwynn-forest}Elwynn{/link}. Des araignées Venom Web nichent sur ses berges, et le cuisinier du Scarlet Raven apprécie leurs pattes pour ses gâteaux. Des {link:the-night-watch}Veilleurs{/link} patrouillent la route du nord toute proche, et l'un d'eux tient le tronçon juste à la sortie de la ville. Sur cette route, un marchand gobelin tient un étal à côté d'un Veilleur solitaire et vend des marchandises rares à quiconque ose le voyage.]=],
		},
	},
})

Translate("frFR", "beggar-s-haunt", {
	title = "Repaire des mendiants",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Repaire des mendiants se trouve à l'extrême est du {link:duskwood}Bois de la Pénombre{/link}, près de la frontière du {link:deadwind-pass}Défilé de Deuillevent{/link}. Les {link:forsaken}Réprouvés{/link} en ont fait un camp caché. Leur expédition fut envoyée au sud sur ordre de {link:varimathras}Varimathras{/link} pour explorer les terres de l'ancien royaume d'{link:azeroth}Azeroth{/link}. Un apothicaire de la {link:royal-apothecary-society}Société royale des apothicaires{/link} y travaille avec un Traqueur noir. Quand un espion humain fut pris à surveiller leur camp, ce furent les orcs de {link:stonard}Stonard{/link} qui s'en emparèrent, et les Réprouvés étaient impatients d'apprendre ce qu'il savait.]=],
		},
	},
})

Translate("frFR", "commander-althea-ebonlocke", {
	title = "Commandant Althea Ebonlocke",
	subtitle = "Chef du Guet de nuit",
	found = "Darkshire, devant l'hôtel de ville",
	hint = [=[Parlez au commandant qui dirige le Guet de nuit de Darkshire.]=],
	allegiance = "Guet de nuit · Darkshire",
	aliases = { "Althea Ebonlocke", "Althea" },
	sections = {
		{
			title = "Résumé",
			text = [=[Althea Ebonlocke commande le {link:the-night-watch}Guet de nuit{/link}, la milice qui garde {link:darkshire}Darkshire{/link} maintenant que les soldats de {link:stormwind-city}Stormwind{/link} sont partis. Elle est sévère et peu patiente, et n'a pas de temps pour les pistes qui ne mènent nulle part. Ses Veilleurs sont trop peu nombreux pour la forêt qu'ils doivent tenir. Elle demande de l'aide à tout étranger disposé à la donner, et ne lui fait pas perdre son temps en cérémonies.]=],
		},
		{
			title = "Importance",
			text = [=[Les gens de {link:darkshire}Darkshire{/link} lui doivent leur survie plus qu'à quiconque. L'historien de la ville la range parmi les héros sans lesquels Darkshire serait tombée.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle tient {link:darkshire}Darkshire{/link} et ses routes avec une poignée de {link:the-night-watch}Veilleurs{/link}.
• Elle envoie des volontaires contre les morts des {link:tranquil-gardens-cemetery}Jardins paisibles{/link} et de {link:raven-hill}Colline-aux-Corbeaux{/link}.
• Elle surveilla {link:stalvan-mistmantle}Stalvan Mistmantle{/link} pendant des années, certaine de sa culpabilité mais incapable de la prouver.
• Elle a perdu certains de ses meilleurs Veilleurs face au chevalier mort errant {link:mor-ladim}Mor'Ladim{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les morts du Bois de la Pénombre",
			hint = "Répondez à l'appel du commandant contre les morts-vivants.",
			text = [=[Tout commença avec les squelettes des {link:tranquil-gardens-cemetery}Jardins paisibles{/link}, juste au sud de la ville. Puis vinrent les rapports de {link:raven-hill}Colline-aux-Corbeaux{/link}, où les morts étaient plus nombreux encore, et enfin du mausolée est du grand cimetière, où nichent les propagateurs de peste. Chaque fois, Althea n'avait aucun Veilleur à envoyer. Chaque fois, un étranger y alla à leur place.]=],
		},
		{
			title = "La preuve",
			hint = [=[Apportez au commandant la preuve qu'elle attend depuis longtemps.]=],
			text = [=[Pendant des années, elle avait surveillé {link:stalvan-mistmantle}Stalvan{/link} sans pouvoir le toucher. Quand les pages du journal furent posées devant elle, et que le greffier de la ville jura que l'écriture correspondait au registre, elle n'eut plus besoin de patience. Elle donna l'ordre que Stalvan soit mis à mort.]=],
		},
		{
			title = "Le chevalier sans repos",
			hint = "Apprenez du commandant le sort de Morgan Ladimore.",
