Translate("frFR", "abercrombie", {
	title = "Abercrombie",
	subtitle = "L'ermite de Colline-aux-Corbeaux",
	found = [=[Une cabane à la lisière nord du Cimetière de Colline-aux-Corbeaux]=],
	hint = [=[Rendez visite au vieil ermite qui vit dans une cabane au-dessus du Cimetière de Colline-aux-Corbeaux.]=],
	allegiance = "Aucune",
	aliases = { "L'Embaumeur", "Embaumeur" },
	sections = {
		{
			title = "Résumé",
			text = [=[Abercrombie semble n'être qu'un vieil homme frêle qui vit seul dans une cabane au-dessus du {link:raven-hill-cemetery}Cimetière de Colline-aux-Corbeaux{/link}. Il n'ose plus prendre la route de la ville, et il demande de menus services aux passants : du fil, un alcool fort, des os de goule pour un épouvantail, une caisse perdue au profit des ogres. Il est reconnaissant, et il rit beaucoup. C'est aussi l'Embaumeur.]=],
		},
		{
			title = "Importance",
			text = [=[Les enfants de {link:darkshire}Darkshire{/link} connaissent l'Embaumeur par un conte du soir. C'était un bon alchimiste, et quand sa femme {link:eliza}Eliza{/link} mourut, le chagrin le rendit fou. Il plaça son propre cœur dans la poitrine de celle-ci pour la ramener. Elle se releva avec une faim de chair humaine, et il dut la garder enterrée. Le conte est vrai, et l'Embaumeur vit à côté de sa tombe.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il rassembla du fil de cheveux de fantôme, du jus de zombie et des côtes de goule par les mains d'étrangers.
• Il bâtit une créature de chair, d'os et de métal pour l'envoyer contre {link:darkshire}Darkshire{/link}.
• Il écrivit au bourgmestre dans une écriture que personne en ville ne savait lire.]=],
		},
		{
			title = "Non consigné",
			text = [=[Le vrai nom de l'ermite, son âge et les années de sa folie ne sont écrits nulle part.]=],
		},
	},
	chapters = {
		{
			title = "Les services d'un vieil homme",
			hint = [=[Aidez l'ermite à obtenir ce qu'il ne peut aller chercher lui-même.]=],
			text = [=[Le fil, disait-il, était pour ses portes et ses fenêtres, pour empêcher les esprits d'entrer. Le jus devait le réchauffer les nuits froides. Les côtes serviraient à un épouvantail contre les goules. Chaque chose, prise seule, était inoffensive. Toutes servirent au même ouvrage.]=],
		},
		{
			title = "La créature à la porte",
			hint = "Découvrez ce que dit vraiment la lettre de l'ermite.",
			text = [=[Une fois traduite, la lettre était une vantardise. Abercrombie s'y disait créateur. Sa dernière œuvre attendait devant sa cabane en grinçant des dents, prête à marcher sur {link:darkshire}Darkshire{/link} à son signal. L'étranger qui l'avait aidé l'avait construite sans le savoir.]=],
		},
	},
	mentions = {
		{ text = "L'ermite" },
		{ text = "Livrer le fil" },
		{ text = "Livraison de jus" },
		{ text = "Effigie de goule" },
		{ text = "Voleurs ogres" },
		{ text = "Note pour le bourgmestre" },
	},
	bonds = {
		{ id = "eliza", name = "Eliza", note = "sa femme" },
		{ id = "stitches", name = "Stitches", note = "sa création" },
		{ id = "lord-ello-ebonlocke", name = "Lord Ello Ebonlocke", note = "a lu sa lettre" },
		{ id = "madame-eva", name = "Madame Eva", note = "a fait son fil" },
	},
})

Translate("frFR", "eliza", {
	title = "Eliza",
	subtitle = "Fiancée de l'Embaumeur",
	found = [=[Sa tombe à côté de la cabane de l'ermite, au-dessus du Cimetière de Colline-aux-Corbeaux]=],
	hint = [=[Trouvez la tombe qui se trouve à côté de la cabane de l'ermite.]=],
	allegiance = "L'Embaumeur",
	sections = {
		{
			title = "Résumé",
			text = [=[Eliza était la femme de l'alchimiste qui devint l'{link:abercrombie}Embaumeur{/link}. Quand elle mourut, il ne put la laisser partir. Il lui donna son propre cœur, et elle revint de la mort. Ce qui se releva n'était pas la femme qu'il avait aimée. Elle s'éveilla avec une faim de la chair des vivants, et son mari l'enterra de nouveau pour la tenir loin du monde.]=],
		},
		{
			title = "Importance",
			text = [=[Eliza est la source du pouvoir de l'{link:abercrombie}Embaumeur{/link}. Son cœur bat toujours en elle, et tant qu'il bat, sa magie noire tient. Pour le briser, les gens de {link:darkshire}Darkshire{/link} doivent d'abord ouvrir sa tombe. Sa tombe est en vue de la porte de son mari. Quoi qu'il ait oublié d'autre, l'Embaumeur l'a gardée près de lui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle repose dans une tombe peu profonde près de la cabane de son mari, au-dessus du {link:raven-hill-cemetery}Cimetière de Colline-aux-Corbeaux{/link}.
• Des gardes à elle la défendent quand on ouvre sa tombe.
• Elle garde le cœur de l'{link:abercrombie}Embaumeur{/link} dans sa poitrine.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun conte ne rapporte la vie d'Eliza avant sa mort, ni comment elle mourut.]=],
		},
	},
	chapters = {
		{
			title = "La tombe ouverte",
			hint = "Creusez la tombe près de la cabane de l'ermite.",
			text = [=[La terre sur la tombe était meuble, comme si on l'avait creusée et comblée plus d'une fois. Dessous se trouvait un cercueil, et de l'intérieur montaient le raclement de griffes et le grincement de dents pourries. Quand on ouvrit le couvercle, Eliza en sortit. On lui prit le cœur, qui battait encore. Le bourgmestre de {link:darkshire}Darkshire{/link} y vit une protection contre le mal du fou, et il jura que le nom de celui qui l'avait rapporté resterait à jamais dans les annales de la ville.]=],
		},
	},
	mentions = {
		{ text = "La fiancée de l'{link:abercrombie}Embaumeur{/link}" },
		{ text = "Fouiller la terre" },
	},
	bonds = {
		{ id = "abercrombie", name = "Abercrombie", note = "son mari" },
		{ id = "lord-ello-ebonlocke", name = "Lord Ello Ebonlocke", note = "a fait chercher le cœur de son mari" },
	},
})

Translate("frFR", "stalvan-mistmantle", {
	title = "Stalvan Mistmantle",
	subtitle = "Le précepteur du Manoir Mistmantle",
	found = "Manoir Mistmantle, au nord de Darkshire",
	hint = "Cherchez la maison solitaire au nord de Darkshire.",
	allegiance = "Aucune",
	aliases = { "Stalvan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Stalvan Mistmantle venait de la {link:silverpine-forest}Forêt des Pins argentés{/link} et étudia auprès du directeur Crillian, dans une académie de {link:stormwind-city}Stormwind{/link}. Il devint précepteur d'enfants, d'abord à {link:moonbrook}Ruisselune{/link}, puis dans la maison d'une famille noble, les Flintridge. Là, il tomba amoureux de son élève Tilloa. Quand elle en choisit un autre, son amour tourna à la haine. Un massacre eut lieu dans la maison Flintridge, et Stalvan vint vivre seul dans les bois au-dessus de {link:darkshire}Darkshire{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Stalvan est la plus sombre légende du {link:duskwood}Bois de la Pénombre{/link}. La vérité à son sujet resta cachée des années dans des pages éparses, une lettre perdue et la mémoire d'un vieux maréchal de {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tint la nouvelle école de {link:moonbrook}Ruisselune{/link} et la quitta quand les troubles arrivèrent dans la {link:westfall}Marche de l'Ouest{/link}.
• Il devint le précepteur de Giles et Tilloa, les enfants de la famille Flintridge.
• Il tint un journal qui consigna son amour pour Tilloa et sa descente dans la rage.]=],
		},
	},
	chapters = {
		{
			title = "La piste des lettres",
			hint = [=[Suivez le nom de Stalvan de Darkshire à Ruisselune et Goldshire.]=],
			text = [=[Le registre de la ville gardait deux adresses de Stalvan. À {link:moonbrook}Ruisselune{/link}, une lettre qu'il n'envoya jamais disait sa joie de bâtir une école. Au Lion's Pride Inn, à {link:goldshire}Goldshire{/link}, une autre attendait, laissée par un messager qui s'enfuit par une nuit d'orage. Stalvan y offrait ses services de précepteur à une maison noble.]=],
		},
		{
			title = "Le journal",
			hint = "Rassemblez les pages éparses du journal de Stalvan.",
			text = [=[Les pages racontent l'histoire de sa propre main. Il y écrivit la beauté de Tilloa, une fleur qu'elle posa dans sa paume, un été au cottage de la famille près du {link:eastvale-logging-camp}Val d'est{/link}. Puis il écrivit sa fureur, quand elle le traita de gentil vieil homme devant son prétendant, et un vide noir qui grandissait en lui. La dernière page promet du sang.]=],
		},
		{
			title = "L'exécution",
			hint = "Exécutez la sentence du Guet de nuit.",
			text = [=[Quand le greffier de {link:darkshire}Darkshire{/link} rapprocha l'écriture du journal de celle du registre, le {link:the-night-watch}Guet de nuit{/link} eut sa preuve. Stalvan mourut dans sa maison, et sa chevalière de famille fut portée à la voyante qui l'avait nommé la première. Elle sentit la forêt respirer plus librement.]=],
		},
	},
	mentions = {
		{ text = "La légende de Stalvan" },
		{ text = "La légende de Stalvan" },
		{ text = "La légende de Stalvan" },
		{ text = "La légende de Stalvan" },
	},
	bonds = {
		{ id = "marshal-haggard", name = "Maréchal Haggard", note = "enquêta sur le massacre" },
		{ id = "madame-eva", name = "Madame Eva", note = "vit son nom dans une vision" },
		{ id = "commander-althea-ebonlocke", name = "Commandant Althea Ebonlocke", note = "ordonna sa mort" },
		{ id = "clerk-daltry", name = "Greffier Daltry", note = "reconnut son écriture" },
	},
})

Translate("frFR", "mor-ladim", {
	title = "Mor'Ladim",
	subtitle = "Le chevalier sans repos",
	found = "Errant dans le Cimetière de Colline-aux-Corbeaux",
	hint = [=[Affrontez le chevalier mort qui erre dans le Cimetière de Colline-aux-Corbeaux.]=],
	allegiance = "Aucune",
	aliases = { "Morgan Ladimore" },
	sections = {
		{
			title = "Résumé",
			text = [=[Morgan Ladimore était un chevalier qui se battait pour les innocents et les pauvres. Il épousa une jeune fille nommée Lys à dix-huit ans, et ils eurent un fils et deux filles. Quand la guerre vint en {link:lordaeron}Lordaeron{/link}, il partit au nord combattre aux côtés d'{link:uther-the-lightbringer}Uther le Porteur de Lumière{/link}. À son retour, il trouva sa forêt pourrie et sa maison en ruine. Il arpente désormais le cimetière sous le nom de Mor'Ladim, une chose morte qui tue sans raison.]=],
		},
		{
			title = "Importance",
			text = [=[La chute de {link:morgan-stern}Morgan{/link} est le conte le plus triste du {link:duskwood}Bois de la Pénombre{/link}. C'était un homme bon brisé par le chagrin. Son nom avertit de ce que les ténèbres de la forêt peuvent faire, même au cœur le plus fort.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il servit {link:uther-the-lightbringer}Uther{/link} pendant la guerre du nord et vit l'ordre des paladins dissous, Uther tué et la peste se répandre.
• Il fouilla chaque ferme et chaque maison du {link:duskwood}Bois de la Pénombre{/link} à la recherche de sa famille.
• Dans le {link:raven-hill-cemetery}Cimetière de Colline-aux-Corbeaux{/link}, il trouva une pierre tombale portant le nom de sa femme.
• Dans son chagrin, il tua trois gardiens du cimetière, puis se donna la mort.]=],
		},
	},
	chapters = {
		{
			title = "La tombe usée",
			hint = [=[Cherchez une tombe à l'extrême bord du Cimetière de Colline-aux-Corbeaux.]=],
			text = [=[On l'enterra à la hâte, sans rites, au-delà de la lisière du cimetière. Quelques jours plus tard, la terre avait été remuée, et la tombe était vide. L'historien de {link:darkshire}Darkshire{/link}, qui avait connu {link:morgan-stern}Morgan{/link} avant la guerre, garde un livre qui raconte son histoire.]=],
		},
		{
			title = "L'anneau d'une fille",
			hint = "Apportez le réconfort à la tombe de Morgan Ladimore.",
			text = [=[{link:morgan-stern}Morgan{/link} mourut en croyant toute sa famille morte. Une fille, Sarah, avait survécu. Quand son anneau fut posé sur sa tombe, une voix s'éleva dans le vent. Le chevalier prononça le nom de sa fille avec émerveillement, et le poids qui pesait sur son âme fut levé. Il donna son épée Archeus à celui qui lui avait apporté la paix, et ses dernières paroles furent pour sa femme, Lys.]=],
		},
	},
	mentions = {
		{ text = "La tombe usée" },
		{ text = "Morgan Ladimore" },
		{ text = "Mor'Ladim" },
		{ text = "L'amour d'une fille" },
	},
	bonds = {
		{ id = "sarah-ladimore", name = "Sarah Ladimore", note = "sa fille" },
		{ id = "sirra-von-indi", name = "Sirra Von'Indi", note = "le connut avant la guerre" },
		{ id = "commander-althea-ebonlocke", name = "Commandant Althea Ebonlocke", note = "le fit traquer" },
		{ id = "uther-the-lightbringer", name = "Uther le Porteur de Lumière", note = "le paladin qu'il servit" },
	},
})

Translate("frFR", "sven-yorgen", {
	title = "Sven Yorgen",
	subtitle = "Vengeur de la ferme des Yorgen",
	found = "Son camp à la frontière ouest du Bois de la Pénombre",
	hint = [=[Trouvez le fermier qui tient un camp à l'extrême bord ouest de la forêt.]=],
	allegiance = "Camp de Sven",
	aliases = { "Sven" },
	sections = {
		{
			title = "Résumé",
			text = [=[Sven Yorgen cultivait jadis une ferme au sud du {link:duskwood}Bois de la Pénombre{/link}. Pendant son absence, des cavaliers en noir sortirent du {link:deadwind-pass}Défilé de Deuillevent{/link} et tuèrent sa famille. Il les poursuivit et perdit leur trace. Il tient désormais un camp à l'ouest avec quelques fidèles et ne vit que pour un but : se venger des {link:dark-riders}cavaliers noirs{/link} et de leur allié, le nécromancien {link:morbent-fel}Morbent Fel{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La fin du nécromancien",
			hint = "Aidez Sven à frapper le nécromancien de la masure lugubre.",
			text = [=[{link:morbent-fel}Morbent Fel{/link} était protégé par des sorts qu'aucune lame ne pouvait franchir. Sven fit demander de l'aide à {link:stormwind-city}Stormwind{/link}. Une arme forgée en fer de forge-lumière, remonté d'un navire coulé de {link:kul-tiras}Kul Tiras{/link}, brisa les protections du nécromancien. Quand Fel tomba, Sven savait que les {link:dark-riders}cavaliers noirs{/link} étaient toujours libres. C'était une petite victoire, et il la prit avec joie.]=],
		},
	},
	mentions = {
		{ text = "La vengeance de Sven" },
		{ text = "Le camp de Sven" },
		{ text = "Retour auprès de Sven" },
		{ text = "En quête de sagesse" },
		{ text = "{link:morbent-fel}Morbent Fel{/link}" },
	},
	bonds = {
		{ id = "morbent-fel", name = "Morbent Fel", note = "son ennemi" },
		{ id = "jitters", name = "Jitters", note = "a vu mourir sa famille" },
	},
})

Translate("frFR", "jitters", {
	title = "Jitters",
	subtitle = "Le survivant du Destin de Roland",
	found = "Caché dans une maison de Colline-aux-Corbeaux",
	hint = [=[Cherchez l'homme effrayé qui se cache dans le village fantôme de Colline-aux-Corbeaux.]=],
	allegiance = "Aucune",
