	},
	bonds = {
		{ id = "sven-yorgen", name = "Sven Yorgen", note = "a juré de le tuer" },
		{ id = "dextren-ward", name = "Dextren Ward", note = "lui vendait des corps" },
	},
})

Translate("frFR", "stitches", {
	title = "Stitches",
	subtitle = "Cadeau de l'Embaumeur",
	found = "La route de Colline-aux-Corbeaux à Darkshire",
	hint = [=[Méfiez-vous de la créature qui descend la route vers Darkshire.]=],
	allegiance = "L'Embaumeur",
	sections = {
		{
			title = "Résumé",
			text = [=[Stitches est la créature de l'{link:abercrombie}Embaumeur{/link}, faite de chair, d'os et de métal tordu. Elle fut construite avec les objets mêmes qu'un étranger avait apportés à la cabane de l'ermite, et elle attendait devant cette cabane le signal de son maître. Quand le signal vint, elle descendit la route vers {link:darkshire}Darkshire{/link} pour massacrer tout ce qu'elle trouverait.]=],
		},
		{
			title = "Importance",
			text = [=[Stitches prouve que le vieux conte d'enfants sur l'{link:abercrombie}Embaumeur{/link} était vrai, et que le fou n'avait pas cessé de fabriquer des choses.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle attendit devant la cabane de l'ermite le signal de son créateur.
• Elle partit pour {link:darkshire}Darkshire{/link} peu après la traduction de la lettre de l'{link:abercrombie}Embaumeur{/link}.]=],
		},
	},
	mentions = {
		{ text = "Traduction pour Ello" },
	},
	bonds = {
		{ id = "abercrombie", name = "Abercrombie", note = "son créateur" },
	},
})

Translate("frFR", "avette-fellwood", {
	title = "Avette Fellwood",
	subtitle = "Facteur d'arcs de Darkshire",
	found = "Darkshire, à son étal de facteur d'arcs",
	hint = [=[Cherchez le facteur d'arcs de Darkshire qui a recueilli un jeune orphelin.]=],
	allegiance = "Darkshire",
	aliases = { "Avette" },
	sections = {
		{
			title = "Résumé",
			text = [=[Avette Fellwood est facteur d'arcs à {link:darkshire}Darkshire{/link}. Elle a récemment adopté Jeremy Heartweaver, un garçon qui survécut à la chute de {link:lordaeron}Lordaeron{/link} et fut amené dans un orphelinat de {link:stormwind-city}Stormwind{/link}. Jeremy n'a plus parlé depuis l'attaque de sa ville. Son père, Edward, se releva parmi les {link:forsaken}Réprouvés{/link} et fouilla chaque semaine les ruines de la capitale à la recherche du corps de son fils, jusqu'au jour où il ne revint pas. Sa dernière lettre, tachée de sang, est parvenue jusqu'à Avette.]=],
		},
		{
			title = "Importance",
			text = [=[Avette choisit de protéger le garçon plutôt que de le blesser. Elle ne lui cachera pas son passé. Elle lui donnera la lettre de son père quand il sera assez grand pour la supporter.]=],
		},
	},
	mentions = {
		{ text = "Souviens-toi que je t'aime" },
	},
	bonds = {
		{ id = "ruins-of-lordaeron", name = "Ruines de Lordaeron", note = "où la lettre fut trouvée" },
	},
})

Translate("frFR", "the-night-watch", {
	title = "Guet de nuit",
	aliases = { "Le Guet de nuit", "Veilleurs" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Guet de nuit est la milice de {link:darkshire}Darkshire{/link}. Il fut levé quand une magie immonde s'infiltra dans le {link:duskwood}Bois de la Pénombre{/link} et que {link:stormwind-city}Stormwind{/link} rappela ses gardes. Depuis, le Guet est tout ce qui se tient entre la ville et la forêt. Il est dirigé par le commandant {link:commander-althea-ebonlocke}Althea Ebonlocke{/link}, et ses membres sont appelés Veilleurs.]=],
		},
		{
			title = "Les Veilleurs",
			text = [=[Des Veilleurs gardent les portes et la place de {link:darkshire}Darkshire{/link}, et quelques-uns tiennent des postes isolés sur les routes : deux sur la route de l'ouest, un sur la route du nord à côté d'un marchand gobelin. Ils sont trop peu nombreux, et ils le savent. Leur commandant ne peut les envoyer loin de la ville. Quand les morts se relèvent dans les cimetières, elle doit demander à des étrangers d'y aller à leur place. Le chevalier mort {link:mor-ladim}Mor'Ladim{/link} a tué certains de ses meilleurs éléments.]=],
		},
		{
			title = "Le Guet et le monde",
			text = [=[{link:darkshire}Darkshire{/link} en est venue à compter sur le Guet comme sur sa seule armée. Quand le magistrat {link:magistrate-solomon}Solomon{/link} de {link:lakeshire}Lakeshire{/link} le demanda à {link:lord-ello-ebonlocke}Lord Ebonlocke{/link}, le bourgmestre refusa : si le Guet partait, la ville tomberait avant qu'il n'atteigne la lisière de la forêt. Tout le monde ne l'admire pas. Le chasseur {link:calor}Calor{/link} quitta le Guet pour {link:carevin-family}la famille Carevin{/link}, le jugeant complaisant. Parmi les Veilleurs figurent {link:sarah-ladimore}Sarah Ladimore{/link}, fille d'un chevalier tombé, et, dans les récits de {link:raven-hill}Colline-aux-Corbeaux{/link}, l'archer Merrick Valor.]=],
		},
	},
})

Translate("frFR", "nightbane-worgen", {
	title = "Worgens Nightbane",
	aliases = { "Nightbane", "worgens Nightbane" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Nightbane sont les {red:worgen}worgens{/red} du {link:duskwood}Bois de la Pénombre{/link} : de grands hommes-loups qui chassent en meutes dans la moitié sud de la forêt. Tisseurs d'ombre et coureurs noirs parcourent le {link:brightwood-grove}Bosquet de Clairbois{/link} et le verger pourrissant. Les plus forts d'entre eux, les crocs infâmes et les souillés, entretiennent leurs feux près des grottes du sud et dans la mine du {link:roland-s-doom}Destin de Roland{/link}.]=],
		},
		{
			title = "Leur venue",
			text = [=[Les worgens n'ont pas toujours été là. Les chasseurs de {link:darkshire}Darkshire{/link} disent qu'ils sont apparus comme sortis de nulle part, et les premiers furent trouvés au {link:roland-s-doom}Destin de Roland{/link}. Un mineur de cette mine, l'homme appelé {link:jitters}Jitters{/link}, raconte comment cela arriva. Il trouva le manche d'une faux dans un tas de gravats et l'en tira. Cette nuit-là, les worgens sortirent de chaque trou et de chaque corniche des tunnels, et la plupart des mineurs moururent. Il perdit la faux dans sa fuite. Il ne sait pas si c'est lui qui amena les hommes-loups dans le {link:duskwood}Bois de la Pénombre{/link}, mais il le craint.

La faux était la {red:scythe-of-elune}Faux d'Elune{/red}. Une prêtresse {link:night-elves}elfe de la nuit{/link}, Velinde Starsong, l'avait portée dans ces bois, et son sort fut découvert dans les mines. Les {link:sentinels}Sentinelles{/link} de {link:darnassus}Darnassus{/link} s'inquiétaient qu'un don de leur déesse ait quitté les mains de ses servantes.]=],
		},
		{
			title = "La guerre contre eux",
			text = [=[La famille {link:carevin-family}Carevin{/link} et son chasseur {link:calor}Calor{/link} mènent une guerre sans fin contre les Nightbane. Chaque meute qu'ils détruisent est vite remplacée. Personne à {link:darkshire}Darkshire{/link} ne sait encore quelle puissance les attire.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours n'explique comment la Faux appela les worgens, ni si les Nightbane sont parents des worgens de la {link:silverpine-forest}Forêt des Pins argentés{/link}.]=],
		},
	},
})

Translate("frFR", "the-valor-family", {
	title = "La famille Valor",
	aliases = { "famille Valor" },
	sections = {
		{
			title = "Résumé",
			text = [=[La famille Valor défendait {link:raven-hill}Colline-aux-Corbeaux{/link} avant sa chute. Un tome trouvé dans le village en ruine, {i}Souvenirs de bravoure{/i}, les évoque un par un. Son auteur les pleure et se reproche leur absence.]=],
		},
		{
			title = "La famille",
			text = [=[• {b}Lord Grant Valor.{/b} Le chef de la famille et le meneur de {link:raven-hill}Colline-aux-Corbeaux{/link}. Quand les ténèbres entrèrent dans les bois, il fut le premier à rallier les villageois. Il haïssait les morts-vivants plus que tout autre ennemi et patrouillait lui-même les cimetières. Une grave blessure qu'ils lui infligèrent ne guérit jamais vraiment.
• {b}Lady Cassandra Valor.{/b} Sa femme. On ne sait guère d'elle que son amour pour sa famille.
• {b}Silvia Valor.{/b} Une garde de Colline-aux-Corbeaux, célèbre pour avoir passé au fil de l'épée bandits et escrocs. On dit qu'elle n'abandonna jamais les fermes du {link:duskwood}Bois de la Pénombre{/link}.
• {b}Ira Valor.{/b} Quand son père tomba malade, elle partit dans la forêt chercher de quoi manger, et elle en vint à préférer les bois obscurs au village. Des voyageurs égarés parlent d'une ombre qui les ramène jusqu'à la route.
• {b}Merrick Valor.{/b} Le fils cadet. Il rejoignit le {link:the-night-watch}Guet de nuit{/link} et garda les routes avec son arc.]=],
		},
		{
			title = "Leurs fantômes",
			text = [=[Les Valor disparurent tous d'un coup. Leurs esprits arpentent désormais la forêt, toujours à l'ouvrage qu'ils faisaient de leur vivant : Grant parmi les squelettes du cimetière, Silvia près des fermes, Ira dans les bois, Merrick sur les routes. {link:sirra-von-indi}Sirra Von'Indi{/link}, l'historien de {link:darkshire}Darkshire{/link}, croit qu'un chagrin partagé les lie à ce monde.]=],
		},
		{
			title = "Non consigné",
			text = [=[Ce qui arriva aux Valor, et ce qui retient leurs esprits, n'est pas encore connu.]=],
		},
	},
})

Translate("frFR", "carevin-family", {
	title = "Famille Carevin",
	aliases = { "Carevin", "la famille Carevin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Carevin sont une maison de {link:darkshire}Darkshire{/link} qui a entrepris une guerre privée. Ils chassent les démons, les morts-vivants et tous ceux qui les aident, et ils ne font confiance à personne qui refuse d'aider leur cause. Leur chef est {link:jonathan-carevin}Jonathan Carevin{/link}. Son chasseur {link:calor}Calor{/link}, autrefois du {link:the-night-watch}Guet de nuit{/link}, mène le combat contre les {link:nightbane-worgen}worgens Nightbane{/link}.]=],
		},
		{
			title = "La maisonnée",
			text = [=[Elaine Carevin veille aux besoins des exclus de la ville. Elle envoie des vivres à {link:sven-yorgen}Sven Yorgen{/link}, à l'ouest, qu'elle appelle un homme qui fait l'œuvre de la Lumière, et elle s'inquiète du vieil ermite qui ne vient plus au marché. Scott Carevin vend des champignons sur la place, et un petit garçon, Benjamin, joue près de la maison.]=],
		},
		{
			title = "Les Carevin et le Guet",
			text = [=[Les Carevin ne s'opposent pas ouvertement au {link:the-night-watch}Guet de nuit{/link}. Pourtant, {link:calor}Calor{/link} ne cache pas son mépris pour lui. Il rêve du jour où les partisans des Carevin seront plus nombreux que les Veilleurs.]=],
		},
	},
})
